// VideoServiceServer is the server API for VideoService service.
// All implementations must embed UnimplementedVideoServiceServer
// for forward compatibility.
type VideoServiceServer interface {
	// CreateUpload mencatat video baru (status PENDING_UPLOAD) dan memulai
	// multipart upload di object storage (langkah 29). File dikirim browser
	// per bagian (part_size_bytes) memakai URL dari PresignUploadParts.
	// Error INVALID_ARGUMENT jika judul, tipe file, atau ukuran tidak valid.
	CreateUpload(context.Context, *CreateUploadRequest) (*CreateUploadResponse, error)
	// PresignUploadParts (langkah 29) memberi URL presigned untuk bagian
	// file yang diminta, dan daftar bagian yang SUDAH tersimpan di storage
	// (untuk melanjutkan upload yang terputus). Error NOT_FOUND jika video
	// tidak ada atau bukan milik requester, FAILED_PRECONDITION jika video
	// tidak sedang menunggu upload, INVALID_ARGUMENT jika nomor bagian salah.
	PresignUploadParts(context.Context, *PresignUploadPartsRequest) (*PresignUploadPartsResponse, error)
	// CompleteUpload dipanggil setelah browser selesai mengunggah semua
	// bagian. Service menggabungkan bagian-bagian itu menjadi satu file,
	// memeriksanya, lalu mengubah status menjadi UPLOADED.
	// Error NOT_FOUND jika video tidak ada atau bukan milik requester,
	// FAILED_PRECONDITION jika file belum ada atau ukurannya tidak sesuai.
	CompleteUpload(context.Context, *CompleteUploadRequest) (*CompleteUploadResponse, error)
	// GetVideo mengambil satu video. Video READY bisa dilihat siapa saja dan
	// diputar lewat video.hls_url. Video yang belum READY (belum selesai
	// diunggah, sedang atau gagal di-transcode) hanya bisa dilihat pemiliknya.
	GetVideo(context.Context, *GetVideoRequest) (*GetVideoResponse, error)
	// ListMyVideos mengambil video milik requester, terbaru lebih dulu.
	ListMyVideos(context.Context, *ListMyVideosRequest) (*ListMyVideosResponse, error)
	// ListVideos mengambil feed publik: hanya video READY, yang paling baru
	// selesai diproses lebih dulu. Boleh dipanggil tanpa login. Isi owner_id
	// untuk daftar video satu channel.
	// Error INVALID_ARGUMENT jika page_size atau page_token tidak valid.
	ListVideos(context.Context, *ListVideosRequest) (*ListVideosResponse, error)
	// RecordView menambah views video READY, maksimal sekali per penonton
	// dalam satu window (default 30 menit). Error NOT_FOUND jika video tidak
	// ada atau belum READY, UNAVAILABLE jika pencatatan views sedang mati.
	RecordView(context.Context, *RecordViewRequest) (*RecordViewResponse, error)
	// LikeVideo menandai video READY disukai requester. Aman dipanggil ulang:
	// like kedua tidak menambah like_count. Error NOT_FOUND jika video tidak
	// ada atau belum READY.
	LikeVideo(context.Context, *LikeVideoRequest) (*LikeVideoResponse, error)
	// UnlikeVideo membatalkan like. Aman dipanggil walau belum pernah like.
	UnlikeVideo(context.Context, *UnlikeVideoRequest) (*UnlikeVideoResponse, error)
	// SearchVideos mencari video READY yang judul atau deskripsinya berisi
	// SEMUA kata di query. Setiap kata cocok dengan awal kata, jadi "gol"
	// menemukan "Golang". Urutan: paling relevan (kata di judul lebih
	// penting), lalu views terbanyak. Boleh dipanggil tanpa login.
	// Error INVALID_ARGUMENT jika query kosong, terlalu panjang, atau tidak
	// berisi kata dengan 2 huruf atau lebih.
	SearchVideos(context.Context, *SearchVideosRequest) (*SearchVideosResponse, error)
	// SaveWatchProgress menyimpan sampai detik berapa requester menonton
	// video READY, untuk riwayat tonton dan "lanjut menonton". Dipanggil
	// player setiap beberapa detik. Aman dipanggil ulang: video yang sama
	// hanya punya satu entri riwayat. Error INVALID_ARGUMENT jika
	// position_ms negatif, NOT_FOUND jika video tidak ada atau belum READY.
	SaveWatchProgress(context.Context, *SaveWatchProgressRequest) (*SaveWatchProgressResponse, error)
	// ListWatchHistory mengambil riwayat tonton requester, yang terakhir
	// ditonton lebih dulu. Hanya video READY.
	ListWatchHistory(context.Context, *ListWatchHistoryRequest) (*ListWatchHistoryResponse, error)
	// DeleteWatchHistory menghapus satu video dari riwayat requester. Aman
	// dipanggil walau video itu tidak ada di riwayat.
	DeleteWatchHistory(context.Context, *DeleteWatchHistoryRequest) (*DeleteWatchHistoryResponse, error)
	// ClearWatchHistory menghapus seluruh riwayat tonton requester.
	ClearWatchHistory(context.Context, *ClearWatchHistoryRequest) (*ClearWatchHistoryResponse, error)
	// UpdateVideo mengganti judul dan/atau deskripsi video milik requester
	// (status apa pun). Kata pencarian ikut diperbarui. Error
	// INVALID_ARGUMENT jika tidak ada field yang dikirim atau isinya tidak
	// valid, NOT_FOUND jika video tidak ada, sudah dihapus, atau bukan milik
	// requester.
	UpdateVideo(context.Context, *UpdateVideoRequest) (*UpdateVideoResponse, error)
	// DeleteVideo menghapus video milik requester dari feed, pencarian,
	// channel, riwayat, komentar, dan danmaku, lalu menghapus file-nya di
	// storage. Error NOT_FOUND jika video tidak ada, sudah dihapus, atau
	// bukan milik requester; FAILED_PRECONDITION jika video sedang
	// di-transcode (UPLOADED atau PROCESSING).
	DeleteVideo(context.Context, *DeleteVideoRequest) (*DeleteVideoResponse, error)
	// ListNotifications mengambil notifikasi requester, terbaru lebih dulu.
	// Notifikasi untuk video yang sudah dihapus tidak ikut.
	ListNotifications(context.Context, *ListNotificationsRequest) (*ListNotificationsResponse, error)
	// CountUnreadNotifications menghitung notifikasi requester yang belum
	// dibaca, maksimal 100 (untuk badge "99+").
	CountUnreadNotifications(context.Context, *CountUnreadNotificationsRequest) (*CountUnreadNotificationsResponse, error)
	// MarkNotificationsRead menandai satu notifikasi, atau semuanya, sebagai
	// sudah dibaca. Aman dipanggil berulang.
	MarkNotificationsRead(context.Context, *MarkNotificationsReadRequest) (*MarkNotificationsReadResponse, error)
	// AddToWatchLater menyimpan video READY ke daftar Tonton nanti requester.
	// Aman dipanggil ulang: video yang sudah tersimpan tidak berubah
	// (added_at tetap waktu pertama disimpan). NOT_FOUND jika video tidak ada
	// atau belum READY.
	AddToWatchLater(context.Context, *AddToWatchLaterRequest) (*AddToWatchLaterResponse, error)
	// RemoveFromWatchLater mengeluarkan video dari daftar Tonton nanti. Aman
	// dipanggil walau video itu tidak ada di daftar.
	RemoveFromWatchLater(context.Context, *RemoveFromWatchLaterRequest) (*RemoveFromWatchLaterResponse, error)
	// ListWatchLater mengambil daftar Tonton nanti requester, yang terakhir
	// disimpan lebih dulu. Hanya video READY.
	ListWatchLater(context.Context, *ListWatchLaterRequest) (*ListWatchLaterResponse, error)
	// CreatePlaylist membuat playlist kosong milik requester.
	// INVALID_ARGUMENT jika judul/deskripsi/visibilitas tidak valid atau
	// requester sudah mencapai batas jumlah playlist.
	CreatePlaylist(context.Context, *CreatePlaylistRequest) (*CreatePlaylistResponse, error)
	// UpdatePlaylist mengubah judul, deskripsi, dan/atau visibilitas.
	UpdatePlaylist(context.Context, *UpdatePlaylistRequest) (*UpdatePlaylistResponse, error)
	// DeletePlaylist menghapus playlist beserta isinya (videonya tidak).
	DeletePlaylist(context.Context, *DeletePlaylistRequest) (*DeletePlaylistResponse, error)
	// GetPlaylist mengambil satu playlist, termasuk jumlah video dan thumbnail.
	GetPlaylist(context.Context, *GetPlaylistRequest) (*GetPlaylistResponse, error)
	// ListPlaylists mengambil playlist milik owner_id, terbaru lebih dulu.
	// PRIVATE hanya ikut jika viewer_id = owner_id.
	ListPlaylists(context.Context, *ListPlaylistsRequest) (*ListPlaylistsResponse, error)
	// AddToPlaylist menambahkan video READY ke akhir playlist. Aman dipanggil
	// ulang: video yang sudah ada tidak berpindah posisi.
	AddToPlaylist(context.Context, *AddToPlaylistRequest) (*AddToPlaylistResponse, error)
	// RemoveFromPlaylist mengeluarkan video dari playlist. Aman dipanggil
	// walau video itu tidak ada di playlist.
	RemoveFromPlaylist(context.Context, *RemoveFromPlaylistRequest) (*RemoveFromPlaylistResponse, error)
	// ListPlaylistVideos mengambil isi playlist sesuai urutan ditambahkan.
	// Hanya video READY.
	ListPlaylistVideos(context.Context, *ListPlaylistVideosRequest) (*ListPlaylistVideosResponse, error)
	// GetChannelStats mengambil statistik channel milik requester untuk
	// dasbor Creator Studio (langkah 22b): tayangan per hari, jumlah danmaku
	// dan komentar yang diterima, untuk periode ini dan periode sebelumnya
	// yang panjangnya sama. Hari dihitung dalam WIB (UTC+7).
	// INVALID_ARGUMENT jika days bukan 7, 28, atau 90.
	GetChannelStats(context.Context, *GetChannelStatsRequest) (*GetChannelStatsResponse, error)
	// SearchPlaylists mencari playlist PUBLIC yang judulnya berisi setiap
	// kata di query (langkah 22c, tab Playlist di halaman pencarian).
	// Playlist tanpa video READY tidak ikut. Urutan: judul yang diawali kata
	// pertama lebih dulu, lalu yang paling baru diperbarui.
	SearchPlaylists(context.Context, *SearchPlaylistsRequest) (*SearchPlaylistsResponse, error)
	// ListTrendingVideos mengambil video READY dengan tayangan terbanyak dalam
	// 7 hari terakhir, termasuk hari ini (tanggal WIB). Langkah 24a, bagian
	// Trending di beranda. Video tanpa tayangan dalam 7 hari tidak ikut.
	ListTrendingVideos(context.Context, *ListTrendingVideosRequest) (*ListTrendingVideosResponse, error)
	// ReportVideo menyimpan laporan requester atas video READY milik orang
	// lain (langkah 24b, tombol Laporkan). Satu laporan per user per video:
	// melapor lagi mengganti alasan dan keterangan. INVALID_ARGUMENT jika
	// alasan tidak dikenal, keterangan terlalu panjang atau kosong untuk
	// alasan OTHER, atau video milik requester sendiri; NOT_FOUND jika video
	// tidak ada atau belum READY.
	ReportVideo(context.Context, *ReportVideoRequest) (*ReportVideoResponse, error)
	// ChooseThumbnailFrame memakai salah satu bingkai buatan transcoder
	// (Video.thumbnail_frames) sebagai thumbnail (langkah 26). NOT_FOUND jika
	// video tidak ada, bukan milik requester, atau posisi bingkai tidak ada.
	ChooseThumbnailFrame(context.Context, *ChooseThumbnailFrameRequest) (*ChooseThumbnailFrameResponse, error)
	// UploadThumbnail menyimpan gambar buatan kreator (JPEG, PNG, atau WebP,
	// maksimal 2 MiB, minimal 320x180) sebagai thumbnail. Gambar dipotong
	// 16:9 dan disimpan ulang sebagai JPEG 1280x720. Boleh sebelum video
	// selesai diproses. INVALID_ARGUMENT jika gambar tidak valid.
	UploadThumbnail(context.Context, *UploadThumbnailRequest) (*UploadThumbnailResponse, error)
	// ListRecommendedVideos menyusun "Rekomendasi untukmu" di Beranda
	// (langkah 27): video publik dengan skor dari tayangan, umur video,
	// kategori yang sering ditonton viewer, kanal yang diikuti viewer, dan
	// sedikit acak dari seed. Video milik viewer dan video yang sudah
	// ditonton sampai hampir habis tidak ikut. Maksimal 2 video per kanal.
	ListRecommendedVideos(context.Context, *ListRecommendedVideosRequest) (*ListRecommendedVideosResponse, error)
	// GetChannelSummary mengambil angka di kepala halaman kanal (jumlah
	// video publik, total tayangan, total suka) dan Video unggulan (langkah
	// 27). Kanal tanpa video menghasilkan angka 0, bukan NOT_FOUND.
	GetChannelSummary(context.Context, *GetChannelSummaryRequest) (*GetChannelSummaryResponse, error)
	// SetFeaturedVideo memilih Video unggulan kanal requester. video_id 0 =
	// tidak ada video unggulan. NOT_FOUND jika video tidak ada atau bukan
	// milik requester; INVALID_ARGUMENT jika video bukan video publik.
	SetFeaturedVideo(context.Context, *SetFeaturedVideoRequest) (*SetFeaturedVideoResponse, error)
	mustEmbedUnimplementedVideoServiceServer()
}

